import anthropic

client = anthropic.Anthropic()

# 1. Upload the file once
with open("annual_balance.pdf", "rb") as f:
    file = client.beta.files.upload(
        file=("annual_balance.pdf", f, "application/pdf"),
        betas=["files-api-2025-04-14"],
    )

# 2. Reuse it across multiple requests, without re-encoding it
for question in ["Summarize the document", "What's the conclusion?", "List the risks"]:
    response = client.beta.messages.create(
        model="claude-opus-4-8",
        max_tokens=1024,
        betas=["files-api-2025-04-14"],
        messages=[{
            "role": "user",
            "content": [
                {"type": "text", "text": question},
                {
                    "type": "document",
                    "source": {"type": "file", "file_id": file.id}
                }
            ]
        }],
    )
    print(response.content[0].text)
